class %order% {
  String _name = '';
  int _level = 1;

  String %order% name {
    return _name.isEmpty ? 'Unknown Hero' : _name;
  }

  %order% name(String newName) {
    if (newName.trim().isNotEmpty) {
      _name = newName.trim();
      print('Hero renamed to: $_name');
    }
  }

  int %order% level => _level;

  %order% level(int newLevel) {
    if (newLevel > 0 && newLevel <= 100) {
      _level = newLevel;
      print('$_name leveled up to $_level!');
    }
  }
}
